export type ConceptRelation =
  | "prerequisite"
  | "produces"
  | "optimizes"
  | "contrasts"
  | "constrains"
  | "evaluates"
  | "extends";

export interface KnowledgeConcept {
  id: string;
  kind?: "concept" | "method" | "metric" | "theorem";
  domain?:
    | "mathematics"
    | "statistics"
    | "physics"
    | "chemistry"
    | "biology"
    | "earth-science"
    | "computer-science"
    | "machine-learning"
    | "distributed-systems";
  label: string;
  definition: string;
  canonicalHref: string;
}

export interface KnowledgeEdge {
  from: string;
  to: string;
  relation: ConceptRelation;
  reason: string;
}

