  "discv4-signed-datagram-envelope": { id: "discv4-signed-datagram-envelope", domain: "distributed-systems", label: "Discv4 signed datagram envelope", definition: "1280-byte 이하 UDP packet의 hash·65-byte recoverable signature·type·RLP data를 순서대로 검증하되 payload confidentiality와 구분하는 wire 경계입니다.", canonicalHref: "/p2p/discv4#wire" },
