  "stun-reflexive-address-discovery": { id: "stun-reflexive-address-discovery", domain: "distributed-systems", label: "STUN reflexive address discovery", definition: "STUN Binding transaction의 XOR-MAPPED-ADDRESS로 server가 관측한 source transport address를 얻되 identity·relay·connectivity 보장과 분리하는 절차입니다.", canonicalHref: "/p2p/nat-traversal#stun" },
